let state=structuredClone(seed);let connected=false;let saveTimer=null;let pendingDraftId=null;let saving=Promise.resolve();
async function request(method,path,payload){const opts={method,headers:{'Accept':'application/json'}};if(payload!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload)}const res=await fetch(path,opts);let out=await res.json().catch(()=>({error:'Invalid server response'}));if(!res.ok)throw new Error(out.error||'API request failed ('+res.status+')');return out;}
async function hydrate(){try{const remote=await request('GET','/api/bootstrap');state={...structuredClone(seed),...remote};connected=true;render();}catch(e){connected=false;console.warn('Backend unavailable; showing local preview only:',e.message);toast('Backend is unavailable — preview actions are temporary');}}
function scheduleDraftSave(){if(!connected)return;pendingDraftId=state.selectedDraft;clearTimeout(saveTimer);saveTimer=setTimeout(()=>void flushDraftSave(),650)}
async function flushDraftSave(){if(!connected)return;clearTimeout(saveTimer);const id=pendingDraftId||state.selectedDraft;pendingDraftId=null;const current=state.drafts.find(x=>x.id===id);if(!current)return;
 saving=saving.catch(()=>{}).then(async()=>{const updated=await request('PUT','/api/drafts/'+encodeURIComponent(id),{title:current.title,body:current.body,altText:state.altText,platforms:current.platforms});Object.assign(current,updated);});await saving;}
async function serverAction(a){if(state.runtime?.mode==="public-read-only"&&a!=="export"){toast("Public demo is read-only");return;}try{
 if(a==='confirmRule'){const title=document.getElementById('ruleTitle')?.value.trim();const phrase=document.getElementById('rulePhrase')?.value.trim();const severity=document.getElementById('ruleSeverity')?.value||'High';if(!title||!phrase){toast('A rule name and prohibited phrase are required');return;}const created=await request('POST','/api/policies/rules',{title,phrase,severity});state.customRules=[...(state.customRules||[]),created.rule];state.policyVersion=created.policyVersion;ui.modal=null;route('policies');toast('Custom rule saved. Revalidate drafts against '+created.policyVersion);return;}
 if(a==='confirmMedia'){const input=document.getElementById('mediaFile');const file=input?.files?.[0];if(!file){toast('Select a PNG or JPEG image');return;}if(file.size>700000){toast('This local version supports images under 700 kB');return;}const altText=document.getElementById('mediaAlt')?.value||'';const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Unable to read image'));reader.readAsDataURL(file)});const uploaded=await request('POST','/api/media',{name:file.name,mime:file.type,base64:String(data).split(',')[1],altText});state.mediaAssets=[uploaded,...(state.mediaAssets||[])];ui.modal=null;route('media');toast('Media saved to local server · '+uploaded.width+' × '+uploaded.height);return;}

 if(a==='confirmDraft'){const title=document.getElementById('modalDraftTitle')?.value.trim();if(!title){toast('Enter a draft title first');return}const d=await request('POST','/api/drafts',{title,campaign:'Q4 Investor Awareness',platforms:'LinkedIn'});state.drafts.unshift(d);state.selectedDraft=d.id;state.findings=[];ui.modal=null;route('studio');toast('Draft created on local server');return;}
 if(a==='saveDraft'){await flushDraftSave();toast('Draft persisted to local Java backend');return;}
 if(a==='runPreflight'||a==='startValidation'){await flushDraftSave();const run=await request('POST','/api/validations',{draftId:state.selectedDraft,platform:state.platform,altText:state.altText});state.findings=run.findings;state.selectedFinding=run.findings[0]?.id||'';state.validationRuns=[run,...(state.validationRuns||[])];route('validation');toast('Server validation '+run.verdict+' · '+run.findings.length+' findings');return;}
 if(a==='approveReview'||a==='requestChanges'){await flushDraftSave();const decision=a==='approveReview'?'Approved':'Changes requested';const target=state.selectedDraft;await request('POST','/api/reviews/'+encodeURIComponent(target)+'/decision',{decision,reviewer:'Local demo reviewer',comment:'Decision recorded from local UI'});state.reviewStatus[target]=decision;const d=state.drafts.find(x=>x.id===target);if(d)d.status=decision;render();toast('Server review decision: '+decision);return;}
 if(a==='certificate'){await flushDraftSave();const cert=await request('POST','/api/releases',{draftId:state.selectedDraft});state.releasesIssued=[cert,...(state.releasesIssued||[])];ui.selectedRelease=cert.id;ui.modal='certificate';render();toast('Evidence certificate created on local server');return;}
 if(a==='resolveIncident'){const result=await request('PATCH','/api/incidents/'+encodeURIComponent(ui.selectedIncident),{status:'Resolved'});let item=state.alerts.find(x=>x.id===result.id);if(item)Object.assign(item,result);render();toast('Incident status saved on server');return;}
 if(a==='resetDemo'){if(!confirm('Reset all stored local demo data?'))return;const r=await request('POST','/api/admin/reset',{});state={...structuredClone(seed),...r};render();toast('Local server data reset');return;}
 if(a==='testWorkflow'){const t=await request('POST','/api/workflows/test',{risk:'high'});toast('Workflow simulated server-side · '+t.trace.length+' steps');return;}
 if(a==='export'){const audit=await request('GET','/api/audit');const blob=new Blob([JSON.stringify(audit,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='postflight-audit-report.json';link.click();URL.revokeObjectURL(url);toast('Audit report downloaded');return;}
 }catch(e){console.error(e);toast('Action rejected: '+e.message);}}

let ui={modal:null,search:false,sidebar:false,workspaceSearch:'',searchText:'',workflowNode:'Legal review',selectedRelease:'PF-REL-2048',selectedIncident:'CMP-018',validationRan:false,addDraftTitle:'',altText:'',showToast:null,template:false};
