const statusTone=x=>['Ready','Approved','Completed','Resolved','Active'].includes(x)?'green':['Blocked','Changes requested','Critical','Open'].includes(x)?'red':['In review','Awaiting brand','Needs changes','Investigating','High'].includes(x)?'amber':'indigo';
function overview(){const data=state.timeframe==='7D'?[55,62,69,61,75,77,88]:state.timeframe==='14D'?[51,58,48,65,75,68,72,78,82,78,87,94,95,100]:[45,61,52,70,62,80,72,87,74,92,88,96,91,100,94,98];const bars=data.map((v,i)=>`<div class="bar-pair"><div class="bar" style="height:${v*.66}%"></div><div class="bar second" style="height:${v*.92}%"></div></div>`).join('');const metrics=[['Sample evaluations','24,816','Illustrative historical chart','layout',''],['Sample pass rate','91.6%','Illustrative historical chart','shield','green'],['Sample approval time','2.4 hrs','Illustrative historical chart','clock',''],['Sample exceptions','08','Illustrative historical chart','alert','red']];return pageHead('ENTERPRISE OVERVIEW','Mission Control','Local content-release operations alongside explicitly illustrative activity benchmarks.',btn('Export report','export','', 'download')+btn('New validation','startValidation','primary','plus'))+`<div class="grid g4" style="margin-bottom:17px">${metrics.map(m=>`<article class="card metric ${m[4]}"><div class="label">${m[0]}</div><div class="mini-icon">${ic(m[3],16)}</div><div class="value">${m[1]}</div><div class="sub">${m[2]}</div></article>`).join('')}</div><div class="split" style="margin-bottom:17px">${panel('Release assurance','Validated content and content requiring review',`<div class="between"><div class="legend"><span><i style="background:#5360d5"></i>Validated</span><span><i style="background:#cdd3fa"></i>For review</span></div><div class="tabbar">${['7D','14D','30D'].map(t=>`<button class="tab ${state.timeframe===t?'selected':''}" data-timeframe="${t}">${t}</button>`).join('')}</div></div><div class="chart" role="img" aria-label="Illustrative validation activity chart">${bars}</div><div class="chart-axis"><span>28 Oct</span><span>31 Oct</span><span>03 Nov</span><span>06 Nov</span><span>09 Nov</span></div>`)}${panel('Compliance health','Risk distribution across active validations',`<div style="display:flex;justify-content:center;padding:2px 0 18px"><div class="round-score">92<span style="font-size:10px;color:var(--muted);font-weight:550">/100</span></div></div>${[['Critical',8,'var(--red)'],['High',24,'var(--orange)'],['Moderate / low',68,'var(--primary)']].map(x=>`<div style="margin:0 0 18px"><div class="between tiny"><b>${x[0]}</b><b>${x[1]}%</b></div><div class="progress" style="margin-top:9px"><i style="width:${x[1]}%;background:${x[2]}"></i></div></div>`).join('')}<div class="notice green">${ic('shield',17)}<span>21 active controls in <strong>FIN-MKT-v3.4</strong></span></div>`)}</div><div class="split">${panel('Recent releases','Illustrative queue plus actual locally issued release certificates',`<div class="table-wrap"><table class="table"><thead><tr><th>Release</th><th>Campaign</th><th>Owner</th><th>Status</th></tr></thead><tbody>${[['PF-REL-2048','Q4 Investor Awareness','Aisha Patel','In review'],['PF-REL-2043','Financial Wellness','Lucas Reed','Ready'],['PF-REL-2037','New Product Launch','Maya Chen','Blocked'],['PF-REL-2033','SME Awareness','Lucas Reed','Approved']].map(r=>`<tr data-route="releases"><td><strong>${r[0]}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td>${badge(r[3],statusTone(r[3]))}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Needs attention','Priority decisions for the compliance team',`<div class="stack">${[['Unverified financial guarantee','FIN-MKT-001 · Legal escalation','red'],['Risk disclaimer missing','FIN-MKT-014 · High risk','amber'],['Approval approaching SLA','Q4 Investor Awareness · 1.5h left','indigo']].map(x=>`<div class="status-row"><span class="badge ${x[2]}">${ic('alert',14)}</span><div><b style="font-size:12.5px">${x[0]}</b><div class="muted tiny" style="margin-top:5px">${x[1]}</div></div></div>`).join('')}</div><button class="btn soft" data-route="validation" style="margin-top:14px;width:100%">Open validation queue ${ic('arrow',15)}</button>`)}</div>`}
